UPDATE proofs SET body_tex = 'By \ref{8JS5}(ii), $\overline{G_\chi} = G_{\bar\chi}$, so $\Re G_\chi = \frac12(G_\chi + G_{\bar\chi})$. As $\mathcal C_\psi$ is closed under $\chi \mapsto \bar\chi$,
\[ \Phi_\psi(s) = \frac12 \sum_{\chi \in \mathcal C_\psi} a_\chi \bigl(H_\chi(s) + H_{\bar\chi}(s)\bigr) \qquad (\Re s > 1). \]
By \ref{8JS6}(ii) the right-hand side is meromorphic on $\Re s > 0$, its poles are simple and lie in $Z$, and at $\rho \in Z$
\[ \operatorname{Res}_{s=\rho} \Phi_\psi = \frac12 \sum_{\chi \in \mathcal C_\psi} a_\chi\, \frac{-m_\chi(\rho) - m_{\bar\chi}(\rho)}{\rho(\rho-1)} = -\frac{S_\rho}{\rho(\rho-1)}, \]
which is nonzero by \ref{8JS5}(v).', body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 14:10:00', updated_by = 'claude' WHERE id = 101;
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '101', 3, 'tighten-proofs-2026-11-24', '{"result_id":111,"body_tex":"By \\ref{8JS5}(ii), $\\overline{G_\\chi} = G_{\\bar\\chi}$, so $\\Re G_\\chi = \\frac12(G_\\chi + G_{\\bar\\chi})$. As $\\mathcal C_\\psi$ is closed under $\\chi \\mapsto \\bar\\chi$,\n\\[ \\Phi_\\psi(s) = \\frac12 \\sum_{\\chi \\in \\mathcal C_\\psi} a_\\chi \\bigl(H_\\chi(s) + H_{\\bar\\chi}(s)\\bigr) \\qquad (\\Re s > 1). \\]\nBy \\ref{8JS6}(ii) the right-hand side is meromorphic on $\\Re s > 0$, its poles are simple and lie in $Z$, and at $\\rho \\in Z$\n\\[ \\operatorname{Res}_{s=\\rho} \\Phi_\\psi = \\frac12 \\sum_{\\chi \\in \\mathcal C_\\psi} a_\\chi\\, \\frac{-m_\\chi(\\rho) - m_{\\bar\\chi}(\\rho)}{\\rho(\\rho-1)} = -\\frac{S_\\rho}{\\rho(\\rho-1)}, \\]\nwhich is nonzero by \\ref{8JS5}(v).","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1}', 'claude');
