UPDATE proofs SET body_tex = '\emph{(i)} $L(s,\chi)$ for $\chi \ne \mathbf 1$ and $(s-1)\zeta(s)$ are entire and not identically zero \cite{Davenport}, so their zeros are discrete; and $\mathcal C_\psi$ is finite.

\emph{(ii)} For $\Re s > 1$ both sides equal $\sum_{n \ge 1} \bar\chi(n)\, n^{-s}$; then use the identity theorem.

\emph{(iii)} If $L(s,\chi) = (s-\rho)^m g(s)$ with $g(\rho) \ne 0$, then by (ii) $L(s,\bar\chi) = (s-\bar\rho)^m\, \overline{g(\bar s)}$.

\emph{(iv)} If $L(\rho,\chi) = 0$ with $\chi \in \mathcal C_\psi$, then $L(\bar\rho,\bar\chi) = 0$ by (iii), and $\bar\chi \in \mathcal C_\psi$ by the \hyperref[8JG8]{definition} of the family.

\emph{(v)} Some $m_\chi(\rho) \ge 1$, every term of $S_\rho$ is nonnegative, and $a_\chi > 0$.', body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 14:10:00', updated_by = 'claude' WHERE id = 105;
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '105', 2, 'tighten-proofs-2026-11-24', '{"result_id":118,"body_tex":"\\emph{(i)} $L(s,\\chi)$ for $\\chi \\ne \\mathbf 1$ and $(s-1)\\zeta(s)$ are entire and not identically zero \\cite{Davenport}, so their zeros are discrete; and $\\mathcal C_\\psi$ is finite.\n\n\\emph{(ii)} For $\\Re s > 1$ both sides equal $\\sum_{n \\ge 1} \\bar\\chi(n)\\, n^{-s}$; then use the identity theorem.\n\n\\emph{(iii)} If $L(s,\\chi) = (s-\\rho)^m g(s)$ with $g(\\rho) \\ne 0$, then by (ii) $L(s,\\bar\\chi) = (s-\\bar\\rho)^m\\, \\overline{g(\\bar s)}$.\n\n\\emph{(iv)} If $L(\\rho,\\chi) = 0$ with $\\chi \\in \\mathcal C_\\psi$, then $L(\\bar\\rho,\\bar\\chi) = 0$ by (iii), and $\\bar\\chi \\in \\mathcal C_\\psi$ by the \\hyperref[8JG8]{definition} of the family.\n\n\\emph{(v)} Some $m_\\chi(\\rho) \\ge 1$, every term of $S_\\rho$ is nonnegative, and $a_\\chi > 0$.","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1}', 'claude');
