UPDATE proofs SET body_tex = 'Since $L(s,\chi) \ne 0$ for $\Re s \ge 1$ \cite{Davenport}, a real $\rho \in Z$ lies in $(0,1)$. By \ref{8JN4} and \ref{8JS5}(v),
\[ \operatorname{Res}_{s=\rho} \Phi_\psi = \frac{S_\rho}{\rho(1-\rho)} > 0. \]', body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 14:10:00', updated_by = 'claude' WHERE id = 107;
